  customer_id INTEGER,
  full_name VARCHAR(64),
  city VARCHAR(64),
  state VARCHAR(64),
  phone_number VARCHAR(64),
  segment VARCHAR(64),
  risk_band VARCHAR(64),
  opened_on VARCHAR(64)
);

